sym_js=',\n'.join(json.dumps(k)+': `'+v.replace('`','\\`')+'`' for k,v in symbols.items())
component=f'''window.NexAgentIcons = (() => {{
  const registry=window.NEX_AGENT_ICONS||[],NS='http://www.w3.org/2000/svg';
  const q=v=>typeof v==='string'?document.querySelector(v):v;
  const getDef=v=>typeof v==='object'?v:registry.find(x=>x.id===v||x.slug===v);
  const clamp=(v,a=0,b=1)=>Math.min(b,Math.max(a,v));
  const symbols={{\n{sym_js}\n  }};
  function paperLayers(){{return `<g class="icon-shadow-layer"><path class="icon-paper-shadow" d="M16 27Q20 14 37 15L82 12Q100 17 103 34L106 79Q101 99 82 104L37 106Q18 101 14 83L12 43Q12 32 16 27Z"/></g><g class="icon-paper-layer"><path class="icon-paper-shape" d="M13 23Q20 12 36 14L84 11Q100 16 105 33L107 78Q103 98 83 103L36 106Q17 100 13 82L10 42Q10 30 13 23Z"/><path class="icon-paper-edge" d="M18 25Q24 18 38 19L82 16Q94 19 99 35L101 76Q97 91 80 97L38 99Q23 94 19 80L16 43Q16 31 18 25Z"/><circle class="icon-active-ring" cx="60" cy="60" r="49"/></g>`}}
  function stateLayer(){{return `<g class="icon-state-layer"><g class="icon-complete-badge"><circle cx="91" cy="29" r="15"/><path d="M84 29L89 34L99 23"/></g></g>`}}
  function sizeBand(size){{return size<=56?'small':size>=144?'large':'medium'}}
  function create(value,config={{}}){{const def=getDef(value);if(!def)throw new Error(`Unknown agent icon: ${{value}}`);const size=Number(config.size||96),treatment=config.treatment||'paper-cutout',allowed=def.states||['inactive','active'];const state=allowed.includes(config.state)?config.state:(config.state==='completed'&&allowed.includes('completed')?'completed':'active');const el=document.createElement('div');el.className='nex-icon nex-agent-icon';el.dataset.iconId=def.id;el.dataset.componentId=def.id;el.dataset.slug=def.slug;el.dataset.treatment=treatment;el.dataset.state=state;el.dataset.sizeBand=sizeBand(size);el.style.setProperty('--icon-size',`${{size}}px`);el.setAttribute('role','img');el.setAttribute('aria-label',config.accessibilityLabel||def.accessibilityLabel);const svg=document.createElementNS(NS,'svg');svg.setAttribute('viewBox','0 0 120 120');svg.setAttribute('class','nex-icon-svg');svg.setAttribute('aria-hidden','true');svg.innerHTML=`${{paperLayers()}}<g class="icon-symbol-layer">${{symbols[def.slug]}}</g><g class="icon-accent-layer"><path class="icon-accent-stroke icon-accent-mark" d="M88 92L97 83"/></g>${{stateLayer()}}`;el.appendChild(svg);const grain=document.createElement('span');grain.className='icon-paper-grain';grain.setAttribute('aria-hidden','true');el.appendChild(grain);if(config.showLabel){{const label=document.createElement('span');label.className='icon-label';label.textContent=config.label||def.name;el.appendChild(label)}}el.__iconConfig={{size,treatment,state,label:config.label||def.name}};return el}}
  class CombinedTimeline{{constructor(entries=[]){{this.entries=entries;this.now=0;this.paused=true;this.timer=null;this._duration=Math.max(0,...entries.map(x=>(x.offset||0)+x.timeline.duration()))}}duration(){{return this._duration}}seek(t){{this.now=clamp(Number(t)||0,0,this._duration);for(const e of this.entries){{const local=this.now-(e.offset||0);e.timeline.seek(local<=0?0:local>=e.timeline.duration()?e.timeline.duration():local)}}return this}}time(v){{return v==null?this.now:this.seek(v)}}progress(v){{return v==null?(this._duration?this.now/this._duration:0):this.seek(v*this._duration)}}pause(){{if(this.timer)cancelAnimationFrame(this.timer);this.timer=null;this.paused=true;return this}}play(from){{if(from!=null)this.seek(from);this.pause();this.paused=false;const initial=this.now,start=performance.now();const tick=now=>{{if(this.paused)return;const t=initial+(now-start)/1000;if(t>=this._duration){{this.seek(this._duration);this.pause();return}}this.seek(t);this.timer=requestAnimationFrame(tick)}};this.timer=requestAnimationFrame(tick);return this}}restart(){{this.seek(0);return this.play()}}kill(){{this.entries.forEach(x=>x.timeline.kill?.());return this.pause()}}}}
  function drawPath(tl,path,start,duration,ease='power2.out'){{if(!path)return;let len=180;try{{len=path.getTotalLength()||180}}catch(_){{}}path.style.strokeDasharray=String(len);tl.addUpdate(start,duration,p=>{{path.style.strokeDashoffset=String(len*(1-p));path.style.opacity=String(p)}},ease)}}
  function stagger(tl,nodes,start,duration,mode='scale'){{const list=[...nodes],seg=duration/Math.max(1,list.length+1);list.forEach((n,i)=>{{const a={{opacity:0,scale:.25,y:mode==='y'?18:0}},b={{opacity:1,scale:1,y:0,duration:seg*2,ease:'back.out(1.7)'}};tl.fromTo(n,a,b,start+i*seg)}})}}
  function genericInternal(el,o){{const tl=NexMotion.createTimeline(),symbol=el.querySelector('.icon-symbol-layer'),accent=el.querySelector('.icon-accent-layer');tl.fromTo(symbol,{{y:8,scale:.9,opacity:.55}},{{y:0,scale:1,opacity:1,duration:o.duration*.68,ease:'power2.out'}},0);tl.fromTo(accent,{{opacity:0,scale:.6}},{{opacity:1,scale:1,duration:o.duration*.5,ease:'back.out(1.7)'}},o.duration*.28);return tl}}
  function bespokeInternal(el,slug,o){{const tl=NexMotion.createTimeline(),S=s=>el.querySelector(s),SA=s=>el.querySelectorAll(s),d=o.duration;switch(slug){{
    case 'agent': tl.fromTo(S('.part-agent-head'),{{y:-12,opacity:0}},{{y:0,opacity:1,duration:d*.45,ease:'back.out(1.7)'}},0);tl.fromTo(S('.part-agent-body'),{{scaleY:.2,opacity:0}},{{scaleY:1,opacity:1,duration:d*.48,ease:'back.out(1.7)'}},d*.12);tl.fromTo(S('.part-agent-orbit'),{{rotation:-80,opacity:0}},{{rotation:0,opacity:1,duration:d*.7,ease:'expo.out'}},d*.2);break;
    case 'multiple-agents': stagger(tl,SA('.part-agent-node'),0,d*.72,'y');drawPath(tl,S('.part-agent-link'),d*.28,d*.5);break;
    case 'prompt': stagger(tl,SA('.part-prompt-line'),0,d*.55,'y');tl.fromTo(S('.part-prompt-caret'),{{opacity:0,scaleX:.05}},{{opacity:1,scaleX:1,duration:d*.45,ease:'power2.out'}},d*.45);break;
    case 'reasoning': stagger(tl,SA('.part-reason-node > *'),0,d*.6);drawPath(tl,S('.part-reason-path'),d*.3,d*.65);break;
    case 'memory': [...SA('.part-memory-card')].forEach((n,i)=>tl.fromTo(n,{{x:-38+i*18,y:-18+i*8,rotation:-9+i*5,opacity:0}},{{x:0,y:0,rotation:0,opacity:1,duration:d*.54,ease:'back.out(1.7)'}},i*d*.12));break;
    case 'context': tl.fromTo(S('.part-context-left'),{{x:21,opacity:.35}},{{x:0,opacity:1,duration:d*.55,ease:'power2.out'}},0);tl.fromTo(S('.part-context-right'),{{x:-21,opacity:.35}},{{x:0,opacity:1,duration:d*.55,ease:'power2.out'}},0);tl.fromTo(S('.part-context-window'),{{scaleX:.25,opacity:0}},{{scaleX:1,opacity:1,duration:d*.65,ease:'back.out(1.7)'}},d*.15);break;
    case 'database': stagger(tl,SA('.part-db-layer'),0,d*.78,'y');break;
    case 'api': stagger(tl,SA('.part-api-node'),0,d*.42);drawPath(tl,S('.part-api-line'),d*.18,d*.55);tl.fromTo(S('.part-api-packet'),{{x:-20,opacity:0}},{{x:40,opacity:1,duration:d*.66,ease:'power2.inOut'}},d*.28);break;
    case 'webhook': drawPath(tl,S('.part-webhook-hook'),0,d*.55);[...SA('.part-webhook-signal')].forEach((n,i)=>drawPath(tl,n,d*(.3+i*.13),d*.42));tl.fromTo(S('.part-webhook-dot'),{{scale:.2,opacity:0}},{{scale:1,opacity:1,duration:d*.35,ease:'back.out(1.7)'}},0);break;
    case 'automation': tl.fromTo(S('.part-auto-gear'),{{rotation:-160,scale:.55,opacity:.3}},{{rotation:0,scale:1,opacity:1,duration:d*.82,ease:'expo.out'}},0);break;
    case 'trigger': tl.fromTo(S('.part-trigger-ring'),{{scale:.55,opacity:0}},{{scale:1,opacity:1,duration:d*.52,ease:'back.out(1.7)'}},0);tl.fromTo(S('.part-trigger-bolt'),{{scale:.2,rotation:-18,opacity:0}},{{scale:1,rotation:0,opacity:1,duration:d*.5,ease:'back.out(1.7)'}},d*.28);break;
    case 'condition': tl.fromTo(S('.part-condition-diamond'),{{rotation:-45,scale:.55,opacity:0}},{{rotation:0,scale:1,opacity:1,duration:d*.58,ease:'back.out(1.7)'}},0);drawPath(tl,S('.part-condition-branch'),d*.26,d*.54);break;
    case 'approval': tl.fromTo(S('.part-approval-paper'),{{y:16,opacity:0}},{{y:0,opacity:1,duration:d*.5,ease:'power2.out'}},0);tl.fromTo(S('.part-approval-stamp'),{{y:-38,scale:1.5,rotation:-14,opacity:0}},{{y:0,scale:1,rotation:0,opacity:1,duration:d*.52,ease:'back.out(1.7)'}},d*.36);break;
    case 'human-review': stagger(tl,[S('.part-human-head'),S('.part-human-body')],0,d*.45);tl.fromTo(S('.part-review-glass'),{{x:22,y:-12,scale:.4,opacity:0}},{{x:0,y:0,scale:1,opacity:1,duration:d*.55,ease:'back.out(1.7)'}},d*.24);drawPath(tl,S('.part-review-check'),d*.55,d*.38);break;
    case 'agent-handoff': stagger(tl,SA('.part-handoff-agent'),0,d*.5);tl.fromTo(S('.part-handoff-token'),{{x:-18,opacity:.35,scale:.7}},{{x:42,opacity:1,scale:1,duration:d*.72,ease:'power2.inOut'}},d*.18);break;
    case 'parallel-tasks': drawPath(tl,S('.icon-symbol-stroke'),0,d*.48);stagger(tl,SA('.part-parallel-task > *'),d*.3,d*.62,'y');break;
    case 'sequential-tasks': [...SA('.part-sequence-step > *')].forEach((n,i)=>tl.fromTo(n,{{scale:.2,opacity:.25}},{{scale:1,opacity:1,duration:d*.35,ease:'back.out(1.7)'}},i*d*.22));break;
    case 'workflow': stagger(tl,SA('.part-workflow-node > *'),0,d*.58);drawPath(tl,S('.part-workflow-line'),d*.28,d*.6);break;
    case 'decision-branch': drawPath(tl,S('.part-decision-trunk'),0,d*.62);tl.fromTo(S('.part-decision-node'),{{rotation:-45,scale:.4,opacity:0}},{{rotation:0,scale:1,opacity:1,duration:d*.45,ease:'back.out(1.7)'}},d*.12);stagger(tl,[S('.branch-a'),S('.branch-b')],d*.46,d*.42);break;
    case 'retry': drawPath(tl,S('.part-retry-arrow'),0,d*.72);tl.fromTo(S('.part-retry-dot'),{{rotation:0,scale:.4}},{{rotation:-360,scale:1,duration:d*.8,ease:'power2.inOut'}},d*.12);break;
    case 'validation': tl.fromTo(S('.part-validation-doc'),{{y:16,opacity:0}},{{y:0,opacity:1,duration:d*.42,ease:'power2.out'}},0);tl.fromTo(S('.part-validation-scan'),{{y:-34,opacity:.15}},{{y:42,opacity:1,duration:d*.55,ease:'power2.inOut'}},d*.18);drawPath(tl,S('.part-validation-check'),d*.55,d*.38);break;
    case 'quality-check': tl.fromTo(S('.part-quality-star'),{{scale:.2,rotation:-90,opacity:0}},{{scale:1,rotation:0,opacity:1,duration:d*.68,ease:'back.out(1.7)'}},0);break;
    case 'payment': tl.fromTo(S('.part-payment-card'),{{x:-22,opacity:0}},{{x:0,opacity:1,duration:d*.45,ease:'power2.out'}},0);tl.fromTo(S('.part-payment-coin'),{{x:28,y:-25,rotation:90,scale:.35,opacity:0}},{{x:0,y:0,rotation:0,scale:1,opacity:1,duration:d*.58,ease:'back.out(1.7)'}},d*.25);break;
    case 'escrow': tl.fromTo(S('.part-escrow-lock'),{{y:-20,scaleY:.6,opacity:.2}},{{y:0,scaleY:1,opacity:1,duration:d*.52,ease:'back.out(1.7)'}},0);stagger(tl,SA('.part-escrow-coins > *'),d*.3,d*.55);break;
    case 'output': drawPath(tl,S('.part-output-arrow'),0,d*.62);tl.fromTo(S('.part-output-tray'),{{y:18,opacity:.3}},{{y:0,opacity:1,duration:d*.45,ease:'back.out(1.7)'}},d*.25);break;
    case 'completed-task': tl.fromTo(S('.part-task-doc'),{{y:18,opacity:0}},{{y:0,opacity:1,duration:d*.45,ease:'power2.out'}},0);tl.fromTo(S('.part-task-check'),{{scale:.2,rotation:-25,opacity:0}},{{scale:1,rotation:0,opacity:1,duration:d*.52,ease:'back.out(1.7)'}},d*.32);break;
    case 'failed-task': tl.fromTo(S('.part-task-doc'),{{y:18,opacity:0}},{{y:0,opacity:1,duration:d*.45,ease:'power2.out'}},0);tl.fromTo(S('.part-task-fail'),{{scale:.2,rotation:25,opacity:0}},{{scale:1,rotation:0,opacity:1,duration:d*.52,ease:'back.out(1.7)'}},d*.32);break;
    case 'processing': tl.fromTo(S('.part-processing-ring'),{{rotation:-160,opacity:.2}},{{rotation:180,opacity:1,duration:d*.88,ease:'power2.inOut'}},0);tl.fromTo(S('.part-processing-bar'),{{scaleX:.05,opacity:.25}},{{scaleX:1,opacity:1,duration:d*.78,ease:'power2.out'}},d*.12);break;
    case 'data-extraction': tl.fromTo(S('.part-extract-doc'),{{x:-20,opacity:0}},{{x:0,opacity:1,duration:d*.42,ease:'power2.out'}},0);[...SA('.part-extract-blocks > *')].forEach((n,i)=>tl.fromTo(n,{{x:-35,opacity:0,scale:.4}},{{x:0,opacity:1,scale:1,duration:d*.42,ease:'back.out(1.7)'}},d*(.25+i*.16)));break;
    case 'transformation': tl.fromTo(S('.part-transform-left'),{{x:0,scale:1,opacity:1}},{{x:22,scale:.25,opacity:0,duration:d*.48,ease:'power2.in'}},0);drawPath(tl,S('.part-transform-arrow'),d*.15,d*.52);tl.fromTo(S('.part-transform-right'),{{x:-25,scale:.25,opacity:0,rotation:-25}},{{x:0,scale:1,opacity:1,rotation:0,duration:d*.56,ease:'back.out(1.7)'}},d*.38);break;
    default:return genericInternal(el,o)
  }}tl.seek(0);return tl}}
  function animate(target,options={{}}){{const el=q(target),def=getDef(el?.dataset.iconId||target);if(!el||!def)throw new Error('Agent icon target missing');const motion=options.motion||def.defaultMotion,duration=Number(options.duration||def.duration.recommended),energy=options.energy||options.motionEnergy||'medium';const entrance=NexMotion.apply(el,`motion.entrance.${{motion}}`,{{duration,energy,ease:options.ease}});const internal=def.bespokeInternalMotion?bespokeInternal(el,def.slug,{{duration:Math.max(.5,duration*.92),energy}}):genericInternal(el,{{duration:Math.max(.45,duration*.76),energy}});const combined=new CombinedTimeline([{{timeline:entrance,offset:0}},{{timeline:internal,offset:Math.max(.08,duration*.22)}}]);combined.seek(0);el.__tl=combined;return combined}}
  function setState(target,state){{const el=q(target),def=getDef(el?.dataset.iconId);if(!el||!def)return el;if(!(def.states||[]).includes(state))state=(def.states||['active']).includes('active')?'active':def.states[0];el.dataset.state=state;el.__iconConfig.state=state;return el}}
  function setTreatment(target,treatment){{const el=q(target);if(el){{el.dataset.treatment=treatment;el.__iconConfig.treatment=treatment}}return el}}
  function setSize(target,size){{const el=q(target);if(el){{size=Number(size)||96;el.style.setProperty('--icon-size',`${{size}}px`);el.dataset.sizeBand=sizeBand(size);el.__iconConfig.size=size}}return el}}
  function update(target,config={{}}){{const el=q(target),def=getDef(el?.dataset.iconId);if(!el||!def)throw new Error('Agent icon target missing');const next=create(def,{{...el.__iconConfig,...config}});el.replaceWith(next);return next}}
  return {{registry,getDef,create,animate,setState,setTreatment,setSize,update,CombinedTimeline}};
}})();'''
