(root/'styles/agent-icons.css').write_text('''.nex-agent-icon .part-agent-head,.nex-agent-icon .part-agent-body,.nex-agent-icon .part-agent-orbit,.nex-agent-icon .part-agent-node,.nex-agent-icon .part-memory-card,.nex-agent-icon .part-context-left,.nex-agent-icon .part-context-right,.nex-agent-icon .part-context-window,.nex-agent-icon .part-db-layer,.nex-agent-icon .part-api-node,.nex-agent-icon .part-api-packet,.nex-agent-icon .part-webhook-hook,.nex-agent-icon .part-webhook-signal,.nex-agent-icon .part-auto-gear,.nex-agent-icon .part-trigger-ring,.nex-agent-icon .part-trigger-bolt,.nex-agent-icon .part-condition-diamond,.nex-agent-icon .part-approval-stamp,.nex-agent-icon .part-review-glass,.nex-agent-icon .part-handoff-agent,.nex-agent-icon .part-handoff-token,.nex-agent-icon .part-parallel-task,.nex-agent-icon .part-sequence-step,.nex-agent-icon .part-workflow-node,.nex-agent-icon .part-decision-node,.nex-agent-icon .part-retry-dot,.nex-agent-icon .part-validation-scan,.nex-agent-icon .part-quality-star,.nex-agent-icon .part-payment-coin,.nex-agent-icon .part-escrow-lock,.nex-agent-icon .part-escrow-coins,.nex-agent-icon .part-output-tray,.nex-agent-icon .part-task-check,.nex-agent-icon .part-task-fail,.nex-agent-icon .part-processing-ring,.nex-agent-icon .part-processing-bar,.nex-agent-icon .part-extract-blocks,.nex-agent-icon .part-transform-left,.nex-agent-icon .part-transform-right{transform-box:fill-box;transform-origin:center}.nex-agent-icon[data-state="completed"] .part-task-check,.nex-agent-icon[data-state="completed"] .part-validation-check{stroke:var(--primary)}''')

