    svg=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 120" data-component-id="{d['id']}"><style>:root{{--paper-surface:#fffdf8;--ink:#171419;--primary:#6d45d8;--secondary:#ffb648;--accent:#f25f3a;--highlight:#ffe681}}.paper{{fill:var(--paper-surface);stroke:var(--ink);stroke-width:3}}.sfill{{fill:var(--primary);stroke:var(--ink);stroke-width:5;stroke-linejoin:round}}.sstroke{{fill:none;stroke:var(--ink);stroke-width:7;stroke-linecap:round;stroke-linejoin:round}}.afill{{fill:var(--secondary);stroke:var(--ink);stroke-width:4}}.astroke{{fill:none;stroke:var(--accent);stroke-width:6;stroke-linecap:round;stroke-linejoin:round}}.hfill{{fill:var(--highlight);stroke:var(--ink);stroke-width:4}}</style><path class="paper" d="M13 23Q20 12 36 14L84 11Q100 16 105 33L107 78Q103 98 83 103L36 106Q17 100 13 82L10 42Q10 30 13 23Z"/><g>{symbols[slug].replace('icon-symbol-fill','sfill').replace('icon-symbol-stroke','sstroke').replace('icon-accent-fill','afill').replace('icon-accent-stroke','astroke').replace('icon-highlight-fill','hfill')}</g></svg>'''
