explorer='''<!doctype html><html lang="en" data-paper-style="technical-notebook"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NexStudio AI, Agent and Automation Icons</title><link rel="stylesheet" href="styles/tokens.css"><link rel="stylesheet" href="styles/paper.css"><link rel="stylesheet" href="styles/motion.css"><link rel="stylesheet" href="styles/icons.css"><link rel="stylesheet" href="styles/agent-icons.css"><link rel="stylesheet" href="styles/icon-explorer.css"><link rel="stylesheet" href="styles/agent-explorer.css"></head><body><div class="icon-app"><aside class="icon-sidebar"><div class="icon-brand">NEXSTUDIO<br>AGENT ICONS</div><div class="icon-kicker">Batch 6 · 48 layered AI and automation components</div><div class="icon-controls"><label class="icon-control">Paper style<select id="agentStyle"><option value="clean-editorial">Clean editorial</option><option value="handmade-scrapbook">Handmade scrapbook</option><option value="technical-notebook" selected>Technical notebook</option><option value="bold-paper-collage">Bold paper collage</option></select></label><label class="icon-control">Palette<select id="agentPalette"><option value="warm">Warm cream / plum</option><option value="cobalt" selected>White / cobalt</option><option value="charcoal">Charcoal / red</option></select></label><div class="agent-colours"><label>Primary<input id="agentPrimary" type="color" value="#1456d8"></label><label>Secondary<input id="agentSecondary" type="color" value="#ffd323"></label><label>Accent<input id="agentAccent" type="color" value="#f25f3a"></label></div><label class="icon-control">Treatment<select id="agentTreatment"><option value="paper-cutout">Paper cutout</option><option value="printed-outline">Printed outline</option></select></label><label class="icon-control">Entrance<select id="agentMotion"><option value="cut-paper-pop">Cut-paper pop</option><option value="paper-slide">Paper slide</option><option value="scale-bounce">Scale bounce</option><option value="drop-and-settle">Drop and settle</option><option value="stamp-impact">Stamp impact</option><option value="unfold">Unfold</option></select></label><label class="icon-control">State<select id="agentState"><option value="active">Active</option><option value="inactive">Inactive</option><option value="completed">Completed where supported</option></select></label><label class="icon-control">Scale<select id="agentSize"><option value="42">Small · 42px</option><option value="96" selected>Medium · 96px</option><option value="176">Large · 176px</option></select></label><label class="icon-control">Motion energy<select id="agentEnergy"><option value="low">Low</option><option value="medium" selected>Medium</option><option value="high">High</option></select></label><label class="icon-control">Search<input id="agentSearch" type="search" placeholder="memory, webhook, handoff…"></label><label class="icon-control"><button id="agentReplayAll">REPLAY VISIBLE ICONS</button></label></div></aside><main class="icon-main"><header class="icon-hero"><h1>THINK.<br>ACT. VERIFY.</h1><div class="icon-counter"><span id="agentCount">48</span> / 48</div></header><p class="icon-summary">AI agents, automation, resources, trust and outputs are represented as reusable layered SVG components with semantic motion that communicates what each operation is doing.</p><div class="icon-toolbar"><button class="icon-filter active" data-filter="all">All</button><button class="icon-filter" data-filter="bespoke">Semantic motion</button><button class="icon-filter" data-filter="ai-core">AI core</button><button class="icon-filter" data-filter="resources">Resources</button><button class="icon-filter" data-filter="automation">Automation</button><button class="icon-filter" data-filter="trust">Trust</button><button class="icon-filter" data-filter="output">Output</button></div><section id="agentGrid" class="icon-grid-surface" aria-live="polite"></section></main></div><aside id="agentManifest" class="icon-manifest-panel"><header><h2>Component manifest</h2><button id="closeAgentManifest">CLOSE</button></header><pre></pre></aside><script src="vendor/gsap-compat.js"></script><script src="runtime/theme.js"></script><script src="runtime/motion-registry.js"></script><script src="runtime/motion-engine.js"></script><script src="runtime/agent-icon-registry.js"></script><script src="components/agent-icons.js"></script><script src="runtime/agent-icon-explorer.js"></script></body></html>'''
(root/'agent-icon-explorer.html').write_text(explorer)
(root/'styles/agent-explorer.css').write_text('''.agent-colours{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.agent-colours label{font:800 8px var(--mono-font);text-transform:uppercase}.agent-colours input{width:100%;height:34px;border:2px solid var(--ink);background:var(--paper-surface);padding:2px}.agent-group{font:900 9px var(--mono-font);text-transform:uppercase;color:var(--ink-muted)}''')
explorer_js='''(()=>{const $=s=>document.querySelector(s),grid=$('#agentGrid'),count=$('#agentCount'),manifest=$('#agentManifest');const c={style:$('#agentStyle'),palette:$('#agentPalette'),treatment:$('#agentTreatment'),motion:$('#agentMotion'),state:$('#agentState'),size:$('#agentSize'),energy:$('#agentEnergy'),search:$('#agentSearch')};let filter='all';function matches(def){const term=c.search.value.trim().toLowerCase(),hay=[def.name,def.slug,def.group,...def.keywords,...def.intents].join(' ').toLowerCase();if(term&&!hay.includes(term))return false;if(filter==='bespoke'&&!def.bespokeInternalMotion)return false;if(!['all','bespoke'].includes(filter)&&def.group!==filter)return false;return true}function state(def){return def.states.includes(c.state.value)?c.state.value:(c.state.value==='completed'?'active':def.states[0])}function card(def){const a=document.createElement('article');a.className='icon-card';a.dataset.iconId=def.id;a.innerHTML=`<header class="icon-card-head"><div><h3>${def.name}</h3><div class="icon-card-id">${def.id}</div></div><div class="icon-card-badges"><span class="icon-card-badge">${def.bespokeInternalMotion?'semantic':'shared'}</span><span class="icon-card-badge">${def.group}</span></div></header><div class="icon-stage"></div><div class="agent-group">${def.intents.join(' · ')}</div><footer class="icon-card-actions"><button data-action="replay">Replay</button><button data-action="manifest">Manifest</button></footer>`;const icon=NexAgentIcons.create(def,{size:Number(c.size.value),treatment:c.treatment.value,state:state(def)});a.querySelector('.icon-stage').appendChild(icon);icon.__tl=NexAgentIcons.animate(icon,{motion:c.motion.value,energy:c.energy.value});icon.__tl.seek(icon.__tl.duration());a.querySelector('[data-action=replay]').onclick=()=>icon.__tl.restart();a.querySelector('[data-action=manifest]').onclick=()=>{manifest.querySelector('pre').textContent=JSON.stringify(def,null,2);manifest.classList.add('open')};return a}function render(){NexTheme.setStyle(c.style.value);NexTheme.applyPalette(c.palette.value);NexTheme.setEnergy(c.energy.value);const defs=NexAgentIcons.registry.filter(matches);grid.replaceChildren(...defs.map(card));count.textContent=defs.length}Object.values(c).forEach(el=>el.addEventListener(el===c.search?'input':'change',render));document.querySelectorAll('.icon-filter').forEach(btn=>btn.onclick=()=>{filter=btn.dataset.filter;document.querySelectorAll('.icon-filter').forEach(x=>x.classList.toggle('active',x===btn));render()});[['agentPrimary','primary'],['agentSecondary','secondary'],['agentAccent','accent']].forEach(([id,key])=>$('#'+id).oninput=e=>document.documentElement.style.setProperty('--'+key,e.target.value));$('#agentReplayAll').onclick=()=>[...grid.querySelectorAll('.nex-icon')].forEach((el,i)=>setTimeout(()=>el.__tl?.restart(),i*22));$('#closeAgentManifest').onclick=()=>manifest.classList.remove('open');window.NexAgentExplorer={render,get filter(){return filter}};render()})();'''
(root/'runtime/agent-icon-explorer.js').write_text(explorer_js)

# Three demonstration compositions.
scene_defs=[
 ('multi-agent-orchestration','16:9',1920,1080,'technical-notebook','cobalt','ORCHESTRATE THE WORK','A coordinated agent team splits the job, hands off context, uses tools and brings the result back together.',['multiple-agents','prompt','parallel-tasks','agent-handoff','tool','workflow','processing','output']),
 ('human-agent-approval','1:1',1080,1080,'clean-editorial','warm','HUMAN IN THE LOOP','The agent validates the result, requests review, receives approval and completes the task with an auditable decision.',['agent','validation','human-review','approval','quality-check','security','notification','completed-task']),
 ('prompt-to-output','9:16',1080,1920,'bold-paper-collage','charcoal','PROMPT TO OUTPUT','Instruction becomes reasoning, context, memory, extraction, transformation, processing and a finished deliverable.',['prompt','reasoning','context','memory','data-extraction','transformation','processing','output'])]
(root/'styles/agent-scenes.css').write_text('''html,body{width:100%;height:100%;overflow:hidden}.agent-scene{position:relative;width:100%;height:100%;overflow:hidden;background:var(--paper-bg);color:var(--ink);isolation:isolate}.agent-scene:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 15% 18%,color-mix(in srgb,var(--secondary) 34%,transparent),transparent 28%),linear-gradient(color-mix(in srgb,var(--ink) 7%,transparent) 1px,transparent 1px),linear-gradient(90deg,color-mix(in srgb,var(--ink) 7%,transparent) 1px,transparent 1px);background-size:auto,42px 42px,42px 42px}.agent-scene-layout{position:relative;z-index:2;width:100%;height:100%;display:grid;grid-template-columns:.88fr 1.12fr;gap:60px;padding:82px 96px}.agent-scene-copy{display:flex;flex-direction:column;justify-content:space-between}.agent-scene-kicker{font:900 14px var(--mono-font);letter-spacing:.13em}.agent-scene h1{font:900 clamp(76px,6.7vw,132px)/.84 var(--display-font);letter-spacing:-.075em;margin:18px 0}.agent-scene p{font:700 22px/1.42 var(--mono-font);color:var(--ink-muted);max-width:700px}.agent-scene-tags{display:flex;gap:10px;flex-wrap:wrap}.agent-scene-tags span{border:2px solid var(--ink);background:var(--paper-surface);box-shadow:4px 4px 0 var(--ink);padding:8px 11px;font:900 11px var(--mono-font)}.agent-icon-board{position:relative;display:grid;grid-template-columns:repeat(4,1fr);grid-template-rows:1fr 1fr;gap:18px;padding:28px;border:3px solid var(--ink);background:var(--paper-surface);box-shadow:15px 17px 0 var(--ink);align-self:stretch}.agent-node{display:grid;place-items:center;border:2px dashed color-mix(in srgb,var(--ink) 60%,transparent);background:color-mix(in srgb,var(--paper-surface) 82%,var(--highlight));min-width:0}.agent-node.hero{grid-column:span 2}.agent-node-label{font:900 9px var(--mono-font);text-transform:uppercase;margin-top:8px}.agent-scene[data-ratio="square"] .agent-scene-layout{grid-template-columns:1fr;grid-template-rows:auto 1fr;padding:54px;gap:28px}.agent-scene[data-ratio="square"] .agent-scene-copy{display:grid;grid-template-columns:1fr .72fr;gap:30px;align-items:end}.agent-scene[data-ratio="square"] h1{font-size:82px}.agent-scene[data-ratio="square"] p{font-size:16px}.agent-scene[data-ratio="square"] .agent-icon-board{grid-template-columns:repeat(4,1fr);min-height:540px}.agent-scene[data-ratio="portrait"] .agent-scene-layout{grid-template-columns:1fr;grid-template-rows:auto 1fr;padding:76px 60px;gap:42px}.agent-scene[data-ratio="portrait"] h1{font-size:114px}.agent-scene[data-ratio="portrait"] p{font-size:22px}.agent-scene[data-ratio="portrait"] .agent-icon-board{grid-template-columns:repeat(2,1fr);grid-template-rows:repeat(4,1fr);min-height:900px}.agent-scene[data-ratio="portrait"] .agent-node.hero{grid-column:span 2}''')
for id_,ratio,w,h,style,palette,title,body,slugs in scene_defs:
    nodes=''.join(f'<div class="agent-node" data-icon="{s}"><div class="agent-mount"></div><div class="agent-node-label">{s.replace("-"," ")}</div></div>' for i,s in enumerate(slugs))
    html=f'''<!doctype html><html lang="en" data-paper-style="{style}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><link rel="stylesheet" href="../styles/tokens.css"><link rel="stylesheet" href="../styles/paper.css"><link rel="stylesheet" href="../styles/motion.css"><link rel="stylesheet" href="../styles/icons.css"><link rel="stylesheet" href="../styles/agent-icons.css"><link rel="stylesheet" href="../styles/agent-scenes.css"></head><body><main id="{id_}" class="agent-scene" data-composition-id="{id_}" data-start="0" data-duration="10.8" data-track-index="1" data-width="{w}" data-height="{h}" data-ratio="{'landscape' if ratio=='16:9' else 'square' if ratio=='1:1' else 'portrait'}"><div class="agent-scene-layout"><section class="agent-scene-copy"><div><div class="agent-scene-kicker">NEXSTUDIO / BATCH 6</div><h1>{title}</h1><p>{body}</p></div><div class="agent-scene-tags"><span>48 AGENT ICONS</span><span>30 SEMANTIC MOTIONS</span><span>AGENT-READABLE</span></div></section><section class="agent-icon-board">{nodes}</section></div></main><script src="../vendor/gsap-compat.js"></script><script src="../runtime/theme.js"></script><script>NexTheme.applyPalette('{palette}');NexTheme.setStyle('{style}')</script><script src="../runtime/motion-registry.js"></script><script src="../runtime/motion-engine.js"></script><script src="../runtime/agent-icon-registry.js"></script><script src="../components/agent-icons.js"></script><script src="../runtime/agent-scene-demo.js"></script></body></html>'''
    (root/'compositions'/f'{id_}.html').write_text(html)
scene_js='''(()=>{const root=document.querySelector('.agent-scene'),nodes=[...root.querySelectorAll('.agent-node')],ratio=root.dataset.ratio;const sizes=ratio==='portrait'?[166,134,134,134,134,134,134,148]:ratio==='square'?[150,112,112,112,112,112,112,126]:[185,112,112,112,112,112,112,140];const entries=[];nodes.forEach((node,i)=>{const def=NexAgentIcons.getDef(node.dataset.icon),icon=NexAgentIcons.create(def,{size:sizes[i]||112,state:i===nodes.length-1&&def.states.includes('completed')?'completed':'active'});node.querySelector('.agent-mount').appendChild(icon);const tl=NexAgentIcons.animate(icon,{duration:1.18+(i%3)*.13,energy:i===0?'high':'medium'});entries.push({timeline:tl,offset:.42+i*.68})});const copy=gsap.timeline({paused:true});copy.fromTo(root.querySelector('.agent-scene-kicker'),{opacity:0,x:-35},{opacity:1,x:0,duration:.5,ease:'power3.out'},.12);copy.fromTo(root.querySelector('h1'),{opacity:0,y:65},{opacity:1,y:0,duration:.75,ease:'expo.out'},.2);copy.fromTo(root.querySelector('p'),{opacity:0,y:28},{opacity:1,y:0,duration:.55,ease:'power2.out'},.5);copy.fromTo(root.querySelector('.agent-icon-board'),{opacity:0,x:60,rotation:2},{opacity:1,x:0,rotation:0,duration:.78,ease:'back.out(1.7)'},.28);copy.fromTo(root.querySelector('.agent-scene-tags'),{opacity:0,y:18},{opacity:1,y:0,duration:.45,ease:'power2.out'},.8);entries.push({timeline:copy,offset:0});const ambient=gsap.timeline({paused:true});nodes.forEach((n,i)=>{const y=i%2?5:-5,r=i%2?.4:-.4;ambient.fromTo(n,{y:0,rotation:0},{y,rotation:r,duration:1.0,ease:'sine.inOut'},6.2+i*.04);ambient.to(n,{y:-y,rotation:-r,duration:1.0,ease:'sine.inOut'},7.2+i*.04);ambient.to(n,{y,rotation:r,duration:1.0,ease:'sine.inOut'},8.2+i*.04);ambient.to(n,{y:0,rotation:0,duration:1.0,ease:'sine.inOut'},9.2+i*.04)});entries.push({timeline:ambient,offset:0});const controller=new NexAgentIcons.CombinedTimeline(entries);controller._duration=10.8;controller.seek(0);window.__timelines=window.__timelines||{};window.__timelines[root.id]=controller;window.seekComposition=t=>controller.seek(t);const p=new URLSearchParams(location.search);if(p.has('t'))controller.seek(Number(p.get('t')));else if(p.get('autoplay')==='1')controller.restart();})();'''
(root/'runtime/agent-scene-demo.js').write_text(scene_js)

(root/'AGENT_ICON_API.md').write_text('''# NexStudio Agent Icon API\n\nBatch 6 adds 48 AI-agent, automation and modern software-workflow icons without changing the approved universal or creator icon APIs.\n\n```js\nconst icon = NexAgentIcons.create("agent-handoff", { size: 144, state: "active", treatment: "paper-cutout" });\nmount.appendChild(icon);\nconst timeline = NexAgentIcons.animate(icon, { motion: "paper-slide", energy: "medium", duration: 1.4 });\ntimeline.restart();\n```\n\nPublic methods: `create`, `animate`, `setState`, `setTreatment`, `setSize`, `update`, `getDef`. Each icon is a five-layer editable SVG and reads the existing NexStudio design tokens.\n''')

old=json.loads((root/'manifests/index.json').read_text());old=[x for x in old if x.get('subtype')!='agent-automation'];old.extend(registry);(root/'manifests/index.json').write_text(json.dumps(old,indent=2))
pkg=json.loads((root/'package.json').read_text());pkg['version']='1.5.0-batch6';pkg['description']='Reusable animated paper foundations, objects, motion primitives and icon systems for creators and AI agents';pkg['scripts'].update({'validate:batch6':'python3 tests/validate_batch6.py','smoke:batch6':'python3 tests/smoke_agent_icons.py','inspect:batch6':'python3 tests/inspect_agent_icons.py','map:batch6':'python3 tests/animation_map_agent_icons.py','render:batch6':'python3 tests/render_agent_icons.py'});(root/'package.json').write_text(json.dumps(pkg,indent=2))
chg=(root/'CHANGELOG.md').read_text();(root/'CHANGELOG.md').write_text('# Changelog\n\n## 1.5.0-batch6\n\n- Added 48 reusable AI-agent, automation and software-workflow layered SVG icons.\n- Added 30 semantic internal animations.\n- Added searchable agent-workflow icon explorer.\n- Added multi-agent orchestration, human-agent approval and prompt-to-output compositions.\n- Expanded the combined registry from 200 to 248 entries while preserving Batch 1–5.\n\n'+chg.split('# Changelog',1)[-1].lstrip())
